def transform_v2(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    sigs=Counter(tuple(row) for row in g)
    common_sig=sigs.most_common(1)[0][0]
    interior=[r for r,row in enumerate(g) if tuple(row)==common_sig]
    fill=Counter(g[interior[0]]).most_common(1)[0][0]
    # Horizontal grid rails are rows with little or no interior fill.
    rs=[r for r,row in enumerate(g) if row.count(fill) < w//2]
    regular_rows=[r for r in range(h) if r not in rs]
    cs=[c for c in range(w) if all(g[r][c]!=fill for r in regular_rows)]
    if len(rs)<2 or len(cs)<2: return [row[:] for row in g]
    rail=Counter(g[r][c] for r in rs for c in cs).most_common(1)[0][0]
    out=[]
    for a,b in zip(rs,rs[1:]):
        row=[]
        for x,y in zip(cs,cs[1:]):
            counts=Counter(v for v in (g[a][x],g[a][y],g[b][x],g[b][y]) if v not in (fill,rail))
            v,n=counts.most_common(1)[0] if counts else (fill,0)
            row.append(v if n>=3 else fill)
        out.append(row)
    # Remove empty frame rows and columns.
    while out and all(v==fill for v in out[0]): out.pop(0)
    while out and all(v==fill for v in out[-1]): out.pop()
    if out:
        while out and all(row[0]==fill for row in out):
            for row in out: row.pop(0)
        while out and all(row[-1]==fill for row in out):
            for row in out: row.pop()
    return out
